from datetime import date, timedelta


class Periodo:
    def __init__(self, inicio, fin):
        self.inicio = inicio
        self.fin = fin

    def __iter__(self):
        dia = self.inicio
        while dia <= self.fin:
            yield dia
            dia += timedelta(days=1)

    def __len__(self):
        return max(0, (self.fin - self.inicio).days + 1)

    def __contains__(self, fecha):
        return self.inicio <= fecha <= self.fin


