from datetime import datetime

TIPOS = {"VOZ", "SMS", "DATOS"}


def leer(ruta):
    with open(ruta, encoding="utf-8") as archivo:
        next(archivo)
        for linea in archivo:
            yield linea.rstrip("\n")


def parsear(lineas):
    for linea in lineas:
        c = linea.split("|")
        yield {
            "cdr_id": int(c[0]),
            "linea_origen": c[1],
            "tipo": c[3],
            "destino": c[4],
            "fecha_inicio": c[5],
            "duracion_seg": int(c[6]),
        }


def fecha_ok(texto):
    try:
        datetime.strptime(texto, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return False
    return True


def validos(cdrs):
    for c in cdrs:
        if c["linea_origen"] and c["tipo"] in TIPOS and c["duracion_seg"] >= 0 and fecha_ok(c["fecha_inicio"]):
            yield c


def por_destino(cdrs):
    totales = {}
    for c in cdrs:
        if c["tipo"] == "VOZ":
