import ast

PROHIBIDOS = {"pandas", "sqlite3", "csv", "requests", "sqlalchemy", "conciliacion.infraestructura"}


def violaciones(fuente):
    nombres = set()
    for nodo in ast.walk(ast.parse(fuente)):
        if isinstance(nodo, ast.Import):
            nombres |= {alias.name for alias in nodo.names}
        elif isinstance(nodo, ast.ImportFrom) and nodo.module:
            nombres.add(nodo.module)
    return {m for m in nombres for p in PROHIBIDOS if m == p or m.startswith(p + ".")}


